parameters.jsCode:
// Split the agent's reply into separate Telegram messages.
// The agent inserts a line containing exactly ---SPLIT--- between businesses.
// Also chunk any single block that exceeds Telegram's ~4096 char limit.
const raw = ($json.output || '').toString();
const parts = raw.includes('---SPLIT---') ? raw.split('---SPLIT---') : [raw];
const chunks = [];
const LIMIT = 3800;
for (const part of parts) {
  let t = part.trim();
  if (!t) continue;
  while (t.length > LIMIT) {
    let cut = t.lastIndexOf('\n', LIMIT);
    if (cut < 1000) cut = LIMIT;
    chunks.push(t.slice(0, cut).trim());
    t = t.slice(cut).trim();
  }
  if (t) chunks.push(t);
}
if (chunks.length === 0) chunks.push('(no reply)');
return chunks.map(c => ({ json: { output: c } }));
